(16759996, 6500, 'Хороший выбор для короткой поездки и размеренного отдыха с городскими маршрутами поблизости. Рядом сочетаются городская жизнь и места для отдыха. Ваш восход — 3-звёздочный отель для самостоятельных путешественников.'),
(17955321, 12000, 'Практичная база для знакомства с городом: после насыщенного дня здесь легко переключиться на отдых. В окрестностях есть зелёные зоны и городские маршруты для прогулок. Park Tower — 4-звёздочный отель для самостоятельных путешественников.'),
(17984122, 5700, 'Подходит для тех, кто ценит городской ритм, интересные места и комфортную остановку. Вокруг есть точки для прогулок, покупок и знакомства с городом. Золотой колос — отель для самостоятельных путешественников.'),
(18610132, 20000, 'Спокойный вариант для городской поездки с удобной отправной точкой для прогулок. В окрестностях есть зелёные зоны и городские маршруты для прогулок. Radisson Blu Leninsky Prospect Hotel, Moscow — 5-звёздочный отель для самостоятельных путешественников.'),
(19051240, 5200, 'Подходит для тех, кто ценит городской ритм, интересные места и комфортную остановку. Рядом сочетаются городская жизнь и места для отдыха. Холидей Инн Сущевский — отель для самостоятельных путешественников.'),
(19202824, 5000, 'Хороший выбор для короткой поездки и размеренного отдыха с городскими маршрутами поблизости. В окрестностях есть зелёные зоны и городские маршруты для прогулок. Amato — отель для самостоятельных путешественников.')) AS v(id, price, description) WHERE h.id = v.id;
